BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
SELECT has_function('public','set_design_qc_enabled',ARRAY['boolean','text'],'Persistent admin switch exists');
SELECT has_function('public','submit_design_revision',ARRAY['uuid','uuid','text','text'],'Immutable revision submission exists');
SELECT has_function('public','decide_design_revision',ARRAY['uuid','uuid','text','text'],'Revision-bound review exists');
INSERT INTO auth.users(id,email) SELECT ('fb000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'qc'||n||'@local.test' FROM generate_series(1,4)n;
INSERT INTO public.users(id,auth_id,username,role,name) SELECT ('fb000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('fb000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'qc_user_'||n,(ARRAY['admin','coordinator','designer','designer'])[n],'QC user '||n FROM generate_series(1,4)n;
INSERT INTO public.doctors(id,name,phone,address,doctor_code,representative_name) VALUES('fb000000-0000-0000-0000-000000000010','QC doctor','01000000000','Local','QC-TEST','Test');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000001',true);
INSERT INTO public.orders(id,case_id,doctor_id,patient_name,items,total_price,cost,shade,production_status,delivery_date,workflow_type,designer_id,design_price)
VALUES('fb000000-0000-0000-0000-000000000011','QC-CASE','fb000000-0000-0000-0000-000000000010','QC patient','[]',900,400,'A1','designing',current_date,'split','fb000000-0000-0000-0000-000000000003',100),
('fb000000-0000-0000-0000-000000000012','QC-HISTORY','fb000000-0000-0000-0000-000000000010','Historical design','[]',900,400,'A1','in_production',current_date,'split','fb000000-0000-0000-0000-000000000003',100);
SELECT is((public.get_design_qc_state('fb000000-0000-0000-0000-000000000011')->>'enabled')::boolean,false,'QC defaults off indefinitely');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000002',true);
SELECT throws_ok($$SELECT public.set_design_qc_enabled(true,'ready')$$,'42501','Admin role required','Coordinator cannot enable QC');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000001',true);
SELECT public.set_design_qc_enabled(true,'QC test activation');
SELECT lives_ok($$UPDATE public.orders SET production_status='final_ready' WHERE case_id='QC-HISTORY'$$,'Activation does not gate historical designs without new files');
-- Synthetic object metadata matches metadata observed from the local Storage API.
INSERT INTO storage.objects(bucket_id,name,metadata) SELECT 'design-qc-files','fb000000-0000-0000-0000-000000000011/fb000000-0000-0000-0000-'||lpad(n::text,12,'0')||'/execution.zip',jsonb_build_object('eTag','"'||lpad(n::text,32,'0')||'"','size',100,'mimetype','application/zip') FROM generate_series(21,24)n;
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000004',true);
SELECT throws_ok($$SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000021','https://files.example.test/package','no preview')$$,'42501','Design access denied','Other designer cannot submit');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000003',true);
SELECT throws_ok($$SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000021','https://files.example.test/package','')$$,'22023','HTML preview or exception reason required','Missing preview needs documented exception');
SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000021','https://files.example.test/package','Standalone HTML not available');
SELECT is((SELECT production_status FROM public.orders WHERE case_id='QC-CASE'),'designing','QC submission does not send unapproved work to execution');
SELECT is((SELECT gross_amount FROM public.financial_obligations WHERE order_id='fb000000-0000-0000-0000-000000000011' AND trigger_type='designer_approved' AND status<>'void'),100::numeric,'Designer earning remains at completion before QC approval');
SELECT throws_ok($$UPDATE public.orders SET production_status='in_production' WHERE case_id='QC-CASE'$$,'23514','Design QC approval or permitted bypass required','Direct update cannot skip gate');
SELECT throws_ok($$SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000021',gen_random_uuid(),'approved','')$$,'42501','Admin role required','Designer cannot approve own work');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000001',true);
SELECT throws_ok($$SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000021',gen_random_uuid(),'rejected','')$$,'22023','Reason required','Rejection notes mandatory');
SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000021','fb000000-0000-0000-0000-000000000031','approved','');
SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000021','fb000000-0000-0000-0000-000000000031','approved','');
SELECT is((SELECT count(*) FROM public.design_qc_events WHERE id='fb000000-0000-0000-0000-000000000031'),1::bigint,'Review retry is idempotent');
SELECT lives_ok($$UPDATE public.orders SET instructions='technical note',design_price=100 WHERE case_id='QC-CASE'$$,'Non-file changes retain approval');
SELECT public.release_design_revision('fb000000-0000-0000-0000-000000000011');
SELECT is((SELECT production_status FROM public.orders WHERE case_id='QC-CASE'),'in_production','Approved revision can enter execution');
SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000022','https://files.example.test/package','updated files without preview');
SELECT throws_ok($$UPDATE public.orders SET production_status='final_ready' WHERE case_id='QC-CASE'$$,'23514','Design QC approval or permitted bypass required','Amended files cannot inherit prior approval');
SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000022',gen_random_uuid(),'rejected','Contacts need correction');
SELECT throws_ok($$SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000022',gen_random_uuid(),'bypassed','rush')$$,'23514','Rejected execution files cannot be bypassed','Admin cannot bypass rejected identical files');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000002',true);
SELECT throws_ok($$SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000022',gen_random_uuid(),'bypassed','rush')$$,'23514','Rejected execution files cannot be bypassed','Coordinator also cannot bypass rejected files');
SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000023','https://files.example.test/package','new amended files');
SELECT throws_ok($$SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000023',gen_random_uuid(),'bypassed','')$$,'22023','Reason required','Bypass reason mandatory');
SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000023',gen_random_uuid(),'bypassed','Urgent documented exception');
SELECT public.release_design_revision('fb000000-0000-0000-0000-000000000011');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000001',true);
SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000023',gen_random_uuid(),'rejected','Later independent review');
SELECT is((SELECT production_status FROM public.orders WHERE case_id='QC-CASE'),'in_production','Later bypass rejection does not automatically stop production');
SELECT lives_ok($$UPDATE public.orders SET production_status='final_ready' WHERE case_id='QC-CASE'$$,'Later bypass rejection alerts follow-up without automatic stop');
SELECT ok(EXISTS(SELECT 1 FROM public.design_qc_events WHERE action='rejected' AND revision_id='fb000000-0000-0000-0000-000000000023'),'Later review remains in history');
SELECT public.set_design_qc_enabled(false,'Office not ready until reopened');
SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000024','https://files.example.test/package','paused submission');
SELECT lives_ok($$UPDATE public.orders SET production_status='in_production' WHERE case_id='QC-CASE'$$,'Paused QC does not obstruct existing work');
SELECT public.set_design_qc_enabled(true,'Reopen explicitly');
SELECT lives_ok($$UPDATE public.orders SET production_status='final_ready' WHERE case_id='QC-CASE'$$,'Reopen does not retroactively gate files submitted while paused');
SELECT public.return_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000004','Assign revised work to another designer');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000003',true);
SELECT throws_ok($$SELECT public.get_design_qc_state('fb000000-0000-0000-0000-000000000011')$$,'42501','Design access denied','Previous designer loses access after reassignment');
SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000004',true);
SELECT is(jsonb_array_length(public.get_design_qc_state('fb000000-0000-0000-0000-000000000011')->'revisions'),4,'Replacement designer receives technical revision history');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$UPDATE public.design_revisions SET execution_url='https://evil.test'$$,'42501',NULL,'Revision rows cannot be rewritten');
SELECT throws_ok($$DELETE FROM public.design_qc_events$$,'42501',NULL,'Operational user cannot delete audit');
SELECT is((SELECT count(*) FROM public.design_qc_control),1::bigint,'Control is readable without write permissions');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
